{
  "source_url": "https://github.com/ethereum/execution-specs/blob/forks/amsterdam/src/ethereum/forks/osaka/fork_types.py",
  "title": "Osaka Execution Spec -- Fork Types",
  "category": "execution-spec",
  "type": "Specification (Python)",
  "layer": "execution",
  "description": "Core type definitions for Osaka fork: Account, Address, Root, VersionedHash, Bloom, Authorization, encode_account, and EMPTY_ACCOUNT.",
  "sub_graphs": [
    {
      "id": "SG-type-aliases",
      "name": "Primitive Type Aliases",
      "description": "Defines fundamental Ethereum type aliases used throughout the Osaka fork specification. These aliases map domain-specific names to their underlying byte/hash representations.",
      "invariants": [
        {
          "id": "INV-address-size",
          "text": "Address is always a 20-byte value (Bytes20), corresponding to the length of an Ethereum address derived from the last 20 bytes of a Keccak-256 hash."
        },
        {
          "id": "INV-root-size",
          "text": "Root is always a 32-byte hash (Hash32), representing a Merkle-Patricia trie root."
        },
        {
          "id": "INV-versioned-hash-size",
          "text": "VersionedHash is always a 32-byte hash (Hash32), used for EIP-4844 blob versioned hashes."
        },
        {
          "id": "INV-bloom-size",
          "text": "Bloom is always a 256-byte value (Bytes256), representing a 2048-bit Bloom filter for log indexing."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-address",
          "name": "Address",
          "type": "Bytes20",
          "description": "Type alias for a 20-byte Ethereum address.",
          "source_line": "Address = Bytes20"
        },
        {
          "id": "SV-root",
          "name": "Root",
          "type": "Hash32",
          "description": "Type alias for a 32-byte Merkle-Patricia trie root hash.",
          "source_line": "Root = Hash32"
        },
        {
          "id": "SV-versioned-hash",
          "name": "VersionedHash",
          "type": "Hash32",
          "description": "Type alias for a 32-byte versioned hash used in EIP-4844 blob transactions.",
          "source_line": "VersionedHash = Hash32"
        },
        {
          "id": "SV-bloom",
          "name": "Bloom",
          "type": "Bytes256",
          "description": "Type alias for a 256-byte (2048-bit) Bloom filter used for log event indexing.",
          "source_line": "Bloom = Bytes256"
        }
      ],
      "data_structures": [],
      "preconditions": [],
      "postconditions": [],
      "state_transitions": [],
      "dependencies": [
        "ethereum_types.bytes.Bytes20",
        "ethereum_types.bytes.Bytes256",
        "ethereum.crypto.hash.Hash32"
      ]
    },
    {
      "id": "SG-account-data-structure",
      "name": "Account Data Structure",
      "description": "Defines the Account dataclass representing the state associated with an Ethereum address. The Account is a frozen (immutable) slotted dataclass containing nonce, balance, and code fields. This is the core state representation for every account in the Ethereum state trie.",
      "invariants": [
        {
          "id": "INV-account-immutable",
          "text": "Account instances are immutable (frozen) once created, enforced by the @slotted_freezable and @dataclass decorators."
        },
        {
          "id": "INV-account-nonce-uint",
          "text": "The nonce field must be an unsigned integer (Uint) representing the number of transactions sent from the account (for EOAs) or the number of contracts created (for contract accounts)."
        },
        {
          "id": "INV-account-balance-u256",
          "text": "The balance field must be a 256-bit unsigned integer (U256) representing the account's balance in Wei."
        },
        {
          "id": "INV-account-code-bytes",
          "text": "The code field must be a byte sequence (Bytes) representing the account's EVM bytecode. For externally owned accounts (EOAs), this is empty."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [
        {
          "id": "DS-account",
          "name": "Account",
          "type": "dataclass",
          "decorators": [
            "@slotted_freezable",
            "@dataclass"
          ],
          "description": "State associated with an address.",
          "fields": [
            {
              "name": "nonce",
              "type": "Uint",
              "description": "Transaction count (EOA) or contract creation count. Prevents replay attacks and determines contract addresses."
            },
            {
              "name": "balance",
              "type": "U256",
              "description": "The account's Ether balance denominated in Wei (1 Ether = 10^18 Wei)."
            },
            {
              "name": "code",
              "type": "Bytes",
              "description": "EVM bytecode associated with the account. Empty bytes for externally owned accounts."
            }
          ],
          "source": "@slotted_freezable\n@dataclass\nclass Account:\n    nonce: Uint\n    balance: U256\n    code: Bytes"
        }
      ],
      "preconditions": [],
      "postconditions": [],
      "state_transitions": [],
      "dependencies": [
        "dataclasses.dataclass",
        "ethereum_types.frozen.slotted_freezable",
        "ethereum_types.numeric.Uint",
        "ethereum_types.numeric.U256",
        "ethereum_types.bytes.Bytes"
      ]
    },
    {
      "id": "SG-empty-account-constant",
      "name": "Empty Account Sentinel",
      "description": "Defines the EMPTY_ACCOUNT constant, a canonical representation of an account with zero nonce, zero balance, and empty code. This sentinel value is used for comparisons to determine whether an account is 'empty' per EIP-161, which affects state pruning and gas cost calculations.",
      "invariants": [
        {
          "id": "INV-empty-nonce-zero",
          "text": "EMPTY_ACCOUNT.nonce is always Uint(0)."
        },
        {
          "id": "INV-empty-balance-zero",
          "text": "EMPTY_ACCOUNT.balance is always U256(0)."
        },
        {
          "id": "INV-empty-code-empty",
          "text": "EMPTY_ACCOUNT.code is always empty bytes (b\"\")."
        },
        {
          "id": "INV-empty-account-immutable",
          "text": "EMPTY_ACCOUNT is a frozen Account instance and cannot be modified after creation."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-empty-account",
          "name": "EMPTY_ACCOUNT",
          "type": "Account",
          "description": "Canonical empty account instance used as a sentinel for EIP-161 empty account checks and state pruning.",
          "source_line": "EMPTY_ACCOUNT = Account(nonce=Uint(0), balance=U256(0), code=b\"\")"
        }
      ],
      "data_structures": [],
      "preconditions": [],
      "postconditions": [],
      "state_transitions": [],
      "dependencies": [
        "SG-account-data-structure"
      ]
    },
    {
      "id": "SG-encode-account",
      "name": "Account RLP Encoding",
      "description": "Defines the encode_account function that serializes an Account dataclass into its RLP-encoded representation for storage in the Ethereum state trie. Notably, storage is not part of the Account dataclass and must be provided separately as a storage root hash. The encoding follows the account state format: [nonce, balance, storage_root, code_hash].",
      "invariants": [
        {
          "id": "INV-encode-rlp-format",
          "text": "The RLP encoding always produces a tuple of exactly four elements in order: (nonce, balance, storage_root, keccak256(code))."
        },
        {
          "id": "INV-encode-code-hashed",
          "text": "The account code is never stored directly; it is always hashed with Keccak-256 before encoding."
        },
        {
          "id": "INV-encode-storage-external",
          "text": "Storage root must be provided externally since it is not part of the Account dataclass. This reflects the separation of account state from account storage in Ethereum's state model."
        }
      ],
      "functions": [
        {
          "id": "FN-encode-account",
          "name": "encode_account",
          "signature": "def encode_account(raw_account_data: Account, storage_root: Bytes) -> Bytes",
          "description": "Encode Account dataclass. Storage is not stored in the Account dataclass, so Accounts cannot be encoded without providing a storage root.",
          "parameters": [
            {
              "name": "raw_account_data",
              "type": "Account",
              "description": "The Account dataclass instance containing nonce, balance, and code."
            },
            {
              "name": "storage_root",
              "type": "Bytes",
              "description": "The Merkle-Patricia trie root hash of the account's storage, provided separately from the Account dataclass."
            }
          ],
          "return_type": "Bytes",
          "return_description": "RLP-encoded bytes of the tuple (nonce, balance, storage_root, keccak256(code)).",
          "source": "def encode_account(raw_account_data: Account, storage_root: Bytes) -> Bytes:\n    return rlp.encode(\n        (\n            raw_account_data.nonce,\n            raw_account_data.balance,\n            storage_root,\n            keccak256(raw_account_data.code),\n        )\n    )"
        }
      ],
      "state_variables": [],
      "data_structures": [],
      "preconditions": [
        {
          "id": "PRE-encode-valid-account",
          "text": "raw_account_data must be a valid Account instance with nonce (Uint), balance (U256), and code (Bytes) fields."
        },
        {
          "id": "PRE-encode-valid-storage-root",
          "text": "storage_root must be a valid Bytes value representing the Merkle root of the account's storage trie."
        }
      ],
      "postconditions": [
        {
          "id": "POST-encode-deterministic",
          "text": "Given the same Account and storage_root inputs, encode_account always produces the same RLP-encoded output (deterministic encoding)."
        },
        {
          "id": "POST-encode-decodable",
          "text": "The returned Bytes can be decoded via RLP to recover the original tuple (nonce, balance, storage_root, code_hash)."
        }
      ],
      "state_transitions": [
        {
          "id": "ST-encode-pure",
          "description": "encode_account is a pure function with no side effects. It does not modify any state; it only transforms input data into an RLP-encoded byte representation."
        }
      ],
      "dependencies": [
        "ethereum_rlp.rlp.encode",
        "ethereum.crypto.hash.keccak256",
        "SG-account-data-structure"
      ]
    },
    {
      "id": "SG-authorization-data-structure",
      "name": "Authorization Data Structure (EIP-7702)",
      "description": "Defines the Authorization dataclass used in set-code transactions (EIP-7702). An Authorization represents a signed delegation that allows an EOA to temporarily set its code to a specified contract address. It contains chain_id for replay protection, the target address, a nonce, and an ECDSA signature (y_parity, r, s).",
      "invariants": [
        {
          "id": "INV-auth-immutable",
          "text": "Authorization instances are immutable (frozen) once created, enforced by the @slotted_freezable and @dataclass decorators."
        },
        {
          "id": "INV-auth-chain-id-u256",
          "text": "The chain_id field is a U256, providing chain-specific replay protection for the authorization."
        },
        {
          "id": "INV-auth-address-20bytes",
          "text": "The address field is an Address (Bytes20), specifying the target contract whose code will be delegated to."
        },
        {
          "id": "INV-auth-nonce-u64",
          "text": "The nonce field is a U64, preventing replay of the same authorization."
        },
        {
          "id": "INV-auth-signature-components",
          "text": "The signature is split into three components: y_parity (U8, recovery bit), r (U256), and s (U256), forming a valid ECDSA signature."
        }
      ],
      "functions": [],
      "state_variables": [],
      "data_structures": [
        {
          "id": "DS-authorization",
          "name": "Authorization",
          "type": "dataclass",
          "decorators": [
            "@slotted_freezable",
            "@dataclass"
          ],
          "description": "The authorization for a set code transaction (EIP-7702).",
          "fields": [
            {
              "name": "chain_id",
              "type": "U256",
              "description": "The chain ID for replay protection. Must match the current chain to be valid."
            },
            {
              "name": "address",
              "type": "Address",
              "description": "The target contract address whose code the EOA delegates to."
            },
            {
              "name": "nonce",
              "type": "U64",
              "description": "Authorization nonce preventing replay of the same delegation."
            },
            {
              "name": "y_parity",
              "type": "U8",
              "description": "ECDSA signature recovery parameter (0 or 1)."
            },
            {
              "name": "r",
              "type": "U256",
              "description": "ECDSA signature r component."
            },
            {
              "name": "s",
              "type": "U256",
              "description": "ECDSA signature s component."
            }
          ],
          "source": "@slotted_freezable\n@dataclass\nclass Authorization:\n    chain_id: U256\n    address: Address\n    nonce: U64\n    y_parity: U8\n    r: U256\n    s: U256"
        }
      ],
      "preconditions": [],
      "postconditions": [],
      "state_transitions": [],
      "dependencies": [
        "dataclasses.dataclass",
        "ethereum_types.frozen.slotted_freezable",
        "ethereum_types.numeric.U8",
        "ethereum_types.numeric.U64",
        "ethereum_types.numeric.U256",
        "SG-type-aliases"
      ]
    }
  ],
