{
  "source_url": "https://github.com/ethereum/execution-specs/blob/forks/amsterdam/src/ethereum/forks/osaka/requests.py",
  "title": "Osaka Execution Spec -- Requests",
  "category": "execution-spec",
  "type": "Specification (Python)",
  "layer": "execution",
  "sub_graphs": [
    {
      "id": "SG-REQUEST-TYPES",
      "name": "EIP-7685 Request Type Constants and Contract Identifiers",
      "description": "Defines the core constants for the EIP-7685 request framework: the three request type byte prefixes (deposit=0x00, withdrawal=0x01, consolidation=0x02), the deposit contract address, and the deposit event signature hash. These constants form the foundation for identifying and categorizing contract-triggered requests that are exposed to the consensus layer.",
      "invariants": [
        {
          "id": "INV-REQTYPE-001",
          "text": "DEPOSIT_REQUEST_TYPE = b'\\x00'. The deposit request type byte is always 0x00."
        },
        {
          "id": "INV-REQTYPE-002",
          "text": "WITHDRAWAL_REQUEST_TYPE = b'\\x01'. The withdrawal request type byte is always 0x01."
        },
        {
          "id": "INV-REQTYPE-003",
          "text": "CONSOLIDATION_REQUEST_TYPE = b'\\x02'. The consolidation request type byte is always 0x02."
        },
        {
          "id": "INV-REQTYPE-004",
          "text": "DEPOSIT_CONTRACT_ADDRESS = 0x00000000219ab540356cbb839cbe05303d7705fa. This is the canonical Ethereum deposit contract address and must not change."
        },
        {
          "id": "INV-REQTYPE-005",
          "text": "DEPOSIT_EVENT_SIGNATURE_HASH = 0x649bbc62d0e31342afea4e5cd82d4049e7e1ee912fc0889aa790803be39038c5. This is the keccak256 hash of the DepositEvent signature and is used to filter deposit logs."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-REQTYPE-001",
          "name": "DEPOSIT_CONTRACT_ADDRESS",
          "type": "Address",
          "value": "0x00000000219ab540356cbb839cbe05303d7705fa",
          "description": "The canonical Ethereum 2.0 deposit contract address. All deposit events must originate from this address to be recognized as valid deposit requests."
        },
        {
          "id": "SV-REQTYPE-002",
          "name": "DEPOSIT_EVENT_SIGNATURE_HASH",
          "type": "Bytes32",
          "value": "0x649bbc62d0e31342afea4e5cd82d4049e7e1ee912fc0889aa790803be39038c5",
          "description": "The keccak256 hash of the deposit event signature. Used as topics[0] filter when scanning receipt logs for deposit events."
        },
        {
          "id": "SV-REQTYPE-003",
          "name": "DEPOSIT_REQUEST_TYPE",
          "type": "bytes",
          "value": "b'\\x00'",
          "description": "Single-byte type prefix for deposit requests in the EIP-7685 framework."
        },
        {
          "id": "SV-REQTYPE-004",
          "name": "WITHDRAWAL_REQUEST_TYPE",
          "type": "bytes",
          "value": "b'\\x01'",
          "description": "Single-byte type prefix for withdrawal requests in the EIP-7685 framework."
        },
        {
          "id": "SV-REQTYPE-005",
          "name": "CONSOLIDATION_REQUEST_TYPE",
          "type": "bytes",
          "value": "b'\\x02'",
          "description": "Single-byte type prefix for consolidation requests in the EIP-7685 framework."
        }
      ],
      "data_structures": [],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [],
      "security_notes": [
        "The deposit contract address is hardcoded and immutable. Any change would constitute a consensus-breaking modification.",
        "Request type bytes must be unique and non-overlapping. Collision of type prefixes would cause misrouting of requests between the execution and consensus layers.",
        "The deposit event signature hash must exactly match the keccak256 of the DepositEvent ABI signature. An incorrect hash would cause all deposit events to be silently missed."
      ]
    },
    {
      "id": "SG-DEPOSIT-ABI-LAYOUT",
      "name": "Deposit Event ABI Encoding Layout",
      "description": "Defines the fixed ABI encoding layout for deposit events emitted by the deposit contract. Specifies exact byte offsets and sizes for the five deposit data fields: pubkey (48 bytes at offset 160), withdrawal_credentials (32 bytes at offset 256), amount (8 bytes at offset 320), signature (96 bytes at offset 384), and index (8 bytes at offset 512). The total deposit event data length is exactly 576 bytes.",
      "invariants": [
        {
          "id": "INV-ABI-001",
          "text": "DEPOSIT_EVENT_LENGTH = 576. Every valid deposit event data blob must be exactly 576 bytes in length."
        },
        {
          "id": "INV-ABI-002",
          "text": "The ABI layout uses fixed offsets: PUBKEY_OFFSET=160, WITHDRAWAL_CREDENTIALS_OFFSET=256, AMOUNT_OFFSET=320, SIGNATURE_OFFSET=384, INDEX_OFFSET=512. These offsets are protocol-defined and immutable."
        },
        {
          "id": "INV-ABI-003",
          "text": "The field sizes are fixed: PUBKEY_SIZE=48, WITHDRAWAL_CREDENTIALS_SIZE=32, AMOUNT_SIZE=8, SIGNATURE_SIZE=96, INDEX_SIZE=8. The total of extracted fields is 48+32+8+96+8 = 192 bytes."
        },
        {
          "id": "INV-ABI-004",
          "text": "The encoded offset values in the first 160 bytes of the data must exactly match the expected constant offsets. Any deviation causes an InvalidBlock exception."
        },
        {
          "id": "INV-ABI-005",
          "text": "The encoded size values at each field's offset position must exactly match the expected constant sizes. Any deviation causes an InvalidBlock exception."
        }
      ],
      "functions": [],
      "state_variables": [
        {
          "id": "SV-ABI-001",
          "name": "DEPOSIT_EVENT_LENGTH",
          "type": "Uint",
          "value": "576",
          "description": "The exact byte length of a valid deposit event data blob."
        },
        {
          "id": "SV-ABI-002",
          "name": "PUBKEY_OFFSET",
          "type": "Uint",
          "value": "160",
          "description": "Byte offset within the deposit event data where the pubkey field begins."
        },
        {
          "id": "SV-ABI-003",
          "name": "WITHDRAWAL_CREDENTIALS_OFFSET",
          "type": "Uint",
          "value": "256",
          "description": "Byte offset within the deposit event data where the withdrawal_credentials field begins."
        },
        {
          "id": "SV-ABI-004",
          "name": "AMOUNT_OFFSET",
          "type": "Uint",
          "value": "320",
          "description": "Byte offset within the deposit event data where the amount field begins."
        },
        {
          "id": "SV-ABI-005",
          "name": "SIGNATURE_OFFSET",
          "type": "Uint",
          "value": "384",
          "description": "Byte offset within the deposit event data where the signature field begins."
        },
        {
          "id": "SV-ABI-006",
          "name": "INDEX_OFFSET",
          "type": "Uint",
          "value": "512",
          "description": "Byte offset within the deposit event data where the index field begins."
        },
        {
          "id": "SV-ABI-007",
          "name": "PUBKEY_SIZE",
          "type": "Uint",
          "value": "48",
          "description": "Size in bytes of the validator public key (BLS12-381 compressed)."
        },
        {
          "id": "SV-ABI-008",
          "name": "WITHDRAWAL_CREDENTIALS_SIZE",
          "type": "Uint",
          "value": "32",
          "description": "Size in bytes of the withdrawal credentials hash."
        },
        {
          "id": "SV-ABI-009",
          "name": "AMOUNT_SIZE",
          "type": "Uint",
          "value": "8",
          "description": "Size in bytes of the deposit amount (little-endian uint64, in Gwei)."
        },
        {
          "id": "SV-ABI-010",
          "name": "SIGNATURE_SIZE",
          "type": "Uint",
          "value": "96",
          "description": "Size in bytes of the BLS12-381 signature."
        },
        {
          "id": "SV-ABI-011",
          "name": "INDEX_SIZE",
          "type": "Uint",
          "value": "8",
          "description": "Size in bytes of the deposit index (little-endian uint64)."
        }
      ],
      "data_structures": [
        {
          "id": "DS-ABI-001",
          "name": "DepositEventLayout",
          "description": "The ABI-encoded deposit event data layout. The first 160 bytes contain 5 big-endian uint256 offset values (each 32 bytes). At each offset, there is a 32-byte big-endian size prefix followed by the actual field data.",
          "fields": [
            {
              "name": "pubkey_offset_slot",
              "type": "bytes[0:32]",
              "value": "big-endian uint256 = 160"
            },
            {
              "name": "withdrawal_credentials_offset_slot",
              "type": "bytes[32:64]",
              "value": "big-endian uint256 = 256"
            },
            {
              "name": "amount_offset_slot",
              "type": "bytes[64:96]",
              "value": "big-endian uint256 = 320"
            },
            {
              "name": "signature_offset_slot",
              "type": "bytes[96:128]",
              "value": "big-endian uint256 = 384"
            },
            {
              "name": "index_offset_slot",
              "type": "bytes[128:160]",
              "value": "big-endian uint256 = 512"
            },
            {
              "name": "pubkey",
              "type": "bytes[192:240]",
              "value": "48-byte BLS12-381 compressed public key (preceded by 32-byte size prefix at offset 160)"
            },
            {
              "name": "withdrawal_credentials",
              "type": "bytes[288:320]",
              "value": "32-byte withdrawal credentials hash (preceded by 32-byte size prefix at offset 256)"
            },
            {
              "name": "amount",
              "type": "bytes[352:360]",
              "value": "8-byte little-endian deposit amount in Gwei (preceded by 32-byte size prefix at offset 320)"
            },
            {
              "name": "signature",
              "type": "bytes[416:512]",
              "value": "96-byte BLS12-381 signature (preceded by 32-byte size prefix at offset 384)"
            },
            {
              "name": "index",
              "type": "bytes[544:552]",
              "value": "8-byte little-endian deposit index (preceded by 32-byte size prefix at offset 512)"
            }
          ]
        }
      ],
      "pre_conditions": [],
      "post_conditions": [],
      "state_transitions": [],
      "security_notes": [
        "The strict validation of all offsets and sizes provides defense-in-depth against malformed or malicious deposit event data. Any deviation from the expected ABI layout is treated as a block-level invalidity, not silently ignored.",
        "Big-endian encoding of offsets within the ABI structure requires careful byte-order handling. Implementations must use Uint.from_be_bytes() correctly.",
        "The 576-byte length check is the first validation gate. If the data length is wrong, no further parsing is attempted."
      ]
    },
    {
